import{_ as a,o as i,c as t,ai as l}from"./chunks/framework.Bke2s2V8.js";const u=JSON.parse('{"title":"BasoBas Viva Guide","description":"","frontmatter":{},"headers":[],"relativePath":"general.md","filePath":"general.md"}'),n={name:"general.md"};function r(o,e,s,d,h,c){return i(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="basobas-viva-guide" tabindex="-1">BasoBas Viva Guide <a class="header-anchor" href="#basobas-viva-guide" aria-label="Permalink to “BasoBas Viva Guide”">​</a></h1><h2 id="_1-project-introduction" tabindex="-1">1. Project Introduction <a class="header-anchor" href="#_1-project-introduction" aria-label="Permalink to “1. Project Introduction”">​</a></h2><h3 id="project-name" tabindex="-1">Project Name <a class="header-anchor" href="#project-name" aria-label="Permalink to “Project Name”">​</a></h3><p>BasoBas</p><h3 id="project-type" tabindex="-1">Project Type <a class="header-anchor" href="#project-type" aria-label="Permalink to “Project Type”">​</a></h3><p>Room and rental accommodation web application</p><h3 id="main-goal" tabindex="-1">Main Goal <a class="header-anchor" href="#main-goal" aria-label="Permalink to “Main Goal”">​</a></h3><p>BasoBas helps landlords publish rental rooms and helps tenants find, request, and communicate about those rooms in a more organized way.</p><h3 id="simple-problem-statement" tabindex="-1">Simple Problem Statement <a class="header-anchor" href="#simple-problem-statement" aria-label="Permalink to “Simple Problem Statement”">​</a></h3><p>Finding a room is often confusing because:</p><ul><li>tenants do not know which room is still available</li><li>landlords receive calls from many people without any proper record</li><li>there is no clear system to approve one tenant and reject others</li><li>exact location and private contact details should not be shared with everyone immediately</li></ul><p>BasoBas solves this by creating a clear request-based rental flow.</p><h2 id="_2-what-the-system-does-in-simple-words" tabindex="-1">2. What The System Does In Simple Words <a class="header-anchor" href="#_2-what-the-system-does-in-simple-words" aria-label="Permalink to “2. What The System Does In Simple Words”">​</a></h2><p>This system works like a digital rental assistant.</p><ul><li>A landlord posts a rental listing.</li><li>A tenant explores listings and sends a booking request.</li><li>The landlord checks the request, talks to the tenant, and decides.</li><li>If the landlord approves one tenant, the system marks the rental as rented.</li><li>Other pending tenants for that same room are automatically rejected.</li><li>The landlord can privately share contact number and Google Maps location only with the selected tenant.</li></ul><p>So the system is not only a listing website. It is also a request management system.</p><h2 id="_3-main-users-of-the-system" tabindex="-1">3. Main Users Of The System <a class="header-anchor" href="#_3-main-users-of-the-system" aria-label="Permalink to “3. Main Users Of The System”">​</a></h2><h3 id="guest-user" tabindex="-1">Guest User <a class="header-anchor" href="#guest-user" aria-label="Permalink to “Guest User”">​</a></h3><p>A guest can open the website and browse public rental listings, but cannot request or manage anything.</p><h3 id="tenant" tabindex="-1">Tenant <a class="header-anchor" href="#tenant" aria-label="Permalink to “Tenant”">​</a></h3><p>A tenant is a user who wants to find a room.</p><p>Tenant can:</p><ul><li>browse available rentals</li><li>save favorite rentals</li><li>send a booking request</li><li>view request status</li><li>cancel request</li><li>delete cancelled request from history</li><li>view landlord shared contact number</li><li>view exact location if the landlord shares it</li></ul><h3 id="landlord" tabindex="-1">Landlord <a class="header-anchor" href="#landlord" aria-label="Permalink to “Landlord”">​</a></h3><p>A landlord is a user who owns or manages rooms.</p><p>Landlord can:</p><ul><li>create rental listing</li><li>edit listing</li><li>delete listing</li><li>make listing inactive</li><li>make rented listing available again</li><li>view all incoming requests</li><li>approve or reject requests</li><li>share private contact number</li><li>share Google Maps location</li><li>see own available and rented listings</li></ul><h2 id="_4-real-life-story-of-the-system" tabindex="-1">4. Real Life Story Of The System <a class="header-anchor" href="#_4-real-life-story-of-the-system" aria-label="Permalink to “4. Real Life Story Of The System”">​</a></h2><p>You can explain the project using this simple story:</p><ol><li>A landlord has one room in Baneshwor.</li><li>The landlord adds that room in BasoBas with rent, facilities, photos, and public location.</li><li>Many tenants can see the room because it is available.</li><li>Interested tenants send requests.</li><li>The landlord receives those requests in profile.</li><li>The landlord can call a tenant, ask questions, and compare tenants.</li><li>If the landlord likes one tenant, the landlord approves that request.</li><li>The room becomes rented automatically.</li><li>All other pending requests for that room are rejected automatically.</li><li>The landlord can now share contact number and exact map location with that tenant.</li><li>If the tenant later leaves the room, the landlord can mark the listing available again.</li></ol><p>This flow is one of the strongest points of the project.</p><h2 id="_5-main-features-of-the-project" tabindex="-1">5. Main Features Of The Project <a class="header-anchor" href="#_5-main-features-of-the-project" aria-label="Permalink to “5. Main Features Of The Project”">​</a></h2><h3 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to “Authentication”">​</a></h3><ul><li>user logs in using Supabase Auth</li><li>user chooses a role: tenant or landlord</li><li>each user gets a profile</li></ul><h3 id="phone-verification" tabindex="-1">Phone Verification <a class="header-anchor" href="#phone-verification" aria-label="Permalink to “Phone Verification”">​</a></h3><ul><li>phone number is verified before important actions</li><li>landlord needs verified phone for trusted sharing and listing actions</li><li>tenant needs verified phone before sending booking request</li></ul><h3 id="rental-listing-management" tabindex="-1">Rental Listing Management <a class="header-anchor" href="#rental-listing-management" aria-label="Permalink to “Rental Listing Management”">​</a></h3><ul><li>landlord adds room details</li><li>landlord uploads images</li><li>landlord adds public location text</li><li>landlord can add exact private Google Maps pin</li><li>landlord can update rental status later</li></ul><h3 id="booking-request-system" tabindex="-1">Booking Request System <a class="header-anchor" href="#booking-request-system" aria-label="Permalink to “Booking Request System”">​</a></h3><ul><li>tenant sends request for a room</li><li>same tenant cannot create multiple active requests for the same room</li><li>many different tenants can request the same available room</li><li>landlord reviews all incoming requests</li><li>landlord approves or rejects</li></ul><h3 id="privacy-controlled-sharing" tabindex="-1">Privacy Controlled Sharing <a class="header-anchor" href="#privacy-controlled-sharing" aria-label="Permalink to “Privacy Controlled Sharing”">​</a></h3><ul><li>landlord contact number is not public to everyone</li><li>exact Google Maps location is also private</li><li>landlord shares these only when comfortable</li></ul><h3 id="realtime-updates" tabindex="-1">Realtime Updates <a class="header-anchor" href="#realtime-updates" aria-label="Permalink to “Realtime Updates”">​</a></h3><ul><li>tenant and landlord can see request changes quickly using Supabase Realtime</li></ul><h2 id="_6-flow-from-tenant-perspective" tabindex="-1">6. Flow From Tenant Perspective <a class="header-anchor" href="#_6-flow-from-tenant-perspective" aria-label="Permalink to “6. Flow From Tenant Perspective”">​</a></h2><h3 id="step-1-sign-up-login" tabindex="-1">Step 1: Sign Up / Login <a class="header-anchor" href="#step-1-sign-up-login" aria-label="Permalink to “Step 1: Sign Up / Login”">​</a></h3><p>The tenant logs in and creates an account.</p><h3 id="step-2-verify-phone" tabindex="-1">Step 2: Verify Phone <a class="header-anchor" href="#step-2-verify-phone" aria-label="Permalink to “Step 2: Verify Phone”">​</a></h3><p>The tenant verifies phone number.</p><p>Why this matters:</p><ul><li>fake users are reduced</li><li>landlord gets real contact information</li><li>the system becomes more trustworthy</li></ul><h3 id="step-3-explore-rentals" tabindex="-1">Step 3: Explore Rentals <a class="header-anchor" href="#step-3-explore-rentals" aria-label="Permalink to “Step 3: Explore Rentals”">​</a></h3><p>Tenant browses available rooms.</p><p>Tenant can check:</p><ul><li>location</li><li>room type</li><li>rent</li><li>number of rooms</li><li>bathroom type</li><li>kitchen availability</li><li>water facility</li><li>images</li><li>landlord information shown publicly</li></ul><h3 id="step-4-save-favorites" tabindex="-1">Step 4: Save Favorites <a class="header-anchor" href="#step-4-save-favorites" aria-label="Permalink to “Step 4: Save Favorites”">​</a></h3><p>If the tenant likes a room but is not ready, it can be saved in favorites.</p><h3 id="step-5-send-booking-request" tabindex="-1">Step 5: Send Booking Request <a class="header-anchor" href="#step-5-send-booking-request" aria-label="Permalink to “Step 5: Send Booking Request”">​</a></h3><p>Tenant opens a room and sends request with:</p><ul><li>move-in date</li><li>stay duration</li><li>optional message</li></ul><h3 id="step-6-wait-for-review" tabindex="-1">Step 6: Wait For Review <a class="header-anchor" href="#step-6-wait-for-review" aria-label="Permalink to “Step 6: Wait For Review”">​</a></h3><p>The request becomes <code>pending</code>.</p><p>Important rule:</p><ul><li>the same tenant cannot send another active request for the same room while one is already pending or approved</li></ul><h3 id="step-7-check-request-status" tabindex="-1">Step 7: Check Request Status <a class="header-anchor" href="#step-7-check-request-status" aria-label="Permalink to “Step 7: Check Request Status”">​</a></h3><p>Tenant sees request status in profile:</p><ul><li>pending</li><li>approved</li><li>rejected</li><li>cancelled</li></ul><h3 id="step-8-if-landlord-shares-contact" tabindex="-1">Step 8: If Landlord Shares Contact <a class="header-anchor" href="#step-8-if-landlord-shares-contact" aria-label="Permalink to “Step 8: If Landlord Shares Contact”">​</a></h3><p>If landlord shares contact number, tenant can call landlord directly from profile.</p><h3 id="step-9-if-landlord-shares-exact-location" tabindex="-1">Step 9: If Landlord Shares Exact Location <a class="header-anchor" href="#step-9-if-landlord-shares-exact-location" aria-label="Permalink to “Step 9: If Landlord Shares Exact Location”">​</a></h3><p>If landlord shares Google Maps pin, tenant sees <code>View in Google Maps</code>.</p><h3 id="step-10-cancel-or-continue" tabindex="-1">Step 10: Cancel Or Continue <a class="header-anchor" href="#step-10-cancel-or-continue" aria-label="Permalink to “Step 10: Cancel Or Continue”">​</a></h3><p>Tenant can cancel an active request.</p><p>If a request is cancelled:</p><ul><li>it can be deleted from history</li><li>it does not block future requests</li></ul><h2 id="_7-flow-from-landlord-perspective" tabindex="-1">7. Flow From Landlord Perspective <a class="header-anchor" href="#_7-flow-from-landlord-perspective" aria-label="Permalink to “7. Flow From Landlord Perspective”">​</a></h2><h3 id="step-1-sign-up-login-1" tabindex="-1">Step 1: Sign Up / Login <a class="header-anchor" href="#step-1-sign-up-login-1" aria-label="Permalink to “Step 1: Sign Up / Login”">​</a></h3><p>Landlord logs in and chooses landlord role.</p><h3 id="step-2-verify-phone-1" tabindex="-1">Step 2: Verify Phone <a class="header-anchor" href="#step-2-verify-phone-1" aria-label="Permalink to “Step 2: Verify Phone”">​</a></h3><p>Landlord verifies phone number.</p><p>Why this matters:</p><ul><li>trusted landlord identity</li><li>phone sharing works properly</li><li>communication becomes safer</li></ul><h3 id="step-3-create-rental-listing" tabindex="-1">Step 3: Create Rental Listing <a class="header-anchor" href="#step-3-create-rental-listing" aria-label="Permalink to “Step 3: Create Rental Listing”">​</a></h3><p>Landlord enters:</p><ul><li>rental type</li><li>area/location</li><li>description</li><li>rent</li><li>room count or flat configuration</li><li>bathroom type</li><li>water facility</li><li>kitchen information</li><li>images</li><li>optional private Google Maps pin</li></ul><h3 id="step-4-receive-tenant-requests" tabindex="-1">Step 4: Receive Tenant Requests <a class="header-anchor" href="#step-4-receive-tenant-requests" aria-label="Permalink to “Step 4: Receive Tenant Requests”">​</a></h3><p>When tenants request a rental, those requests appear in landlord profile.</p><p>Landlord sees:</p><ul><li>tenant name</li><li>tenant email</li><li>tenant phone</li><li>move-in date</li><li>stay duration</li><li>tenant message</li></ul><h3 id="step-5-call-and-review" tabindex="-1">Step 5: Call And Review <a class="header-anchor" href="#step-5-call-and-review" aria-label="Permalink to “Step 5: Call And Review”">​</a></h3><p>The landlord can call the tenant and ask:</p><ul><li>job or student status</li><li>number of people staying</li><li>move-in plan</li><li>budget details</li><li>house rule compatibility</li></ul><p>This is an important non-technical part of the project. The system supports decision making, not just data entry.</p><h3 id="step-6-share-contact-number" tabindex="-1">Step 6: Share Contact Number <a class="header-anchor" href="#step-6-share-contact-number" aria-label="Permalink to “Step 6: Share Contact Number”">​</a></h3><p>While request is pending or approved, landlord can share personal contact number with that tenant.</p><p>This is useful when:</p><ul><li>landlord wants the tenant to call back later</li><li>landlord wants direct conversation</li><li>landlord is interested but has not approved yet</li></ul><h3 id="step-7-approve-or-reject" tabindex="-1">Step 7: Approve Or Reject <a class="header-anchor" href="#step-7-approve-or-reject" aria-label="Permalink to “Step 7: Approve Or Reject”">​</a></h3><p>If approved:</p><ul><li>rental becomes rented automatically</li><li>other pending requests on same rental are rejected automatically</li></ul><p>If rejected:</p><ul><li>tenant is informed through request status</li></ul><h3 id="step-8-share-exact-map-location" tabindex="-1">Step 8: Share Exact Map Location <a class="header-anchor" href="#step-8-share-exact-map-location" aria-label="Permalink to “Step 8: Share Exact Map Location”">​</a></h3><p>After or during communication, landlord can share the exact Google Maps location.</p><p>This keeps privacy safer because:</p><ul><li>not every visitor sees the exact address</li><li>only selected tenant gets the exact location</li></ul><h3 id="step-9-manage-listing-later" tabindex="-1">Step 9: Manage Listing Later <a class="header-anchor" href="#step-9-manage-listing-later" aria-label="Permalink to “Step 9: Manage Listing Later”">​</a></h3><p>Landlord can:</p><ul><li>edit details</li><li>delete listing</li><li>mark inactive</li><li>make rented room available again when tenant leaves</li></ul><h2 id="_8-important-business-rules" tabindex="-1">8. Important Business Rules <a class="header-anchor" href="#_8-important-business-rules" aria-label="Permalink to “8. Important Business Rules”">​</a></h2><p>These rules are important for viva because they show system logic clearly.</p><h3 id="rule-1" tabindex="-1">Rule 1 <a class="header-anchor" href="#rule-1" aria-label="Permalink to “Rule 1”">​</a></h3><p>Only landlords can create and manage rental listings.</p><h3 id="rule-2" tabindex="-1">Rule 2 <a class="header-anchor" href="#rule-2" aria-label="Permalink to “Rule 2”">​</a></h3><p>Only verified tenants can send booking requests.</p><h3 id="rule-3" tabindex="-1">Rule 3 <a class="header-anchor" href="#rule-3" aria-label="Permalink to “Rule 3”">​</a></h3><p>Many tenants can request the same room while it is still available.</p><h3 id="rule-4" tabindex="-1">Rule 4 <a class="header-anchor" href="#rule-4" aria-label="Permalink to “Rule 4”">​</a></h3><p>The same tenant cannot have more than one active request for the same rental.</p><h3 id="rule-5" tabindex="-1">Rule 5 <a class="header-anchor" href="#rule-5" aria-label="Permalink to “Rule 5”">​</a></h3><p>If one tenant is approved, that room becomes rented.</p><h3 id="rule-6" tabindex="-1">Rule 6 <a class="header-anchor" href="#rule-6" aria-label="Permalink to “Rule 6”">​</a></h3><p>If one tenant is approved, other pending requests for the same room are rejected automatically.</p><h3 id="rule-7" tabindex="-1">Rule 7 <a class="header-anchor" href="#rule-7" aria-label="Permalink to “Rule 7”">​</a></h3><p>Private contact number and exact location are not shown publicly.</p><h3 id="rule-8" tabindex="-1">Rule 8 <a class="header-anchor" href="#rule-8" aria-label="Permalink to “Rule 8”">​</a></h3><p>Cancelled requests can be deleted from tenant history.</p><h3 id="rule-9" tabindex="-1">Rule 9 <a class="header-anchor" href="#rule-9" aria-label="Permalink to “Rule 9”">​</a></h3><p>Landlord can make rented room available again if tenant leaves.</p><h2 id="_9-public-information-vs-private-information" tabindex="-1">9. Public Information Vs Private Information <a class="header-anchor" href="#_9-public-information-vs-private-information" aria-label="Permalink to “9. Public Information Vs Private Information”">​</a></h2><h3 id="public-information" tabindex="-1">Public Information <a class="header-anchor" href="#public-information" aria-label="Permalink to “Public Information”">​</a></h3><p>These are visible in listing pages:</p><ul><li>general location</li><li>rent</li><li>room type</li><li>facilities</li><li>images</li><li>landlord basic public details</li></ul><h3 id="private-information" tabindex="-1">Private Information <a class="header-anchor" href="#private-information" aria-label="Permalink to “Private Information”">​</a></h3><p>These are not visible to everyone:</p><ul><li>exact Google Maps pin</li><li>shared landlord phone number</li><li>internal request details between landlord and tenant</li></ul><p>This is a good point to explain data privacy in your project.</p><h2 id="_10-main-database-tables" tabindex="-1">10. Main Database Tables <a class="header-anchor" href="#_10-main-database-tables" aria-label="Permalink to “10. Main Database Tables”">​</a></h2><p>You do not need to explain every column in viva. Focus on why each table exists.</p><h3 id="profiles" tabindex="-1"><code>profiles</code> <a class="header-anchor" href="#profiles" aria-label="Permalink to “profiles”">​</a></h3><p>Stores user profile information such as role and phone verification.</p><h3 id="rentals" tabindex="-1"><code>rentals</code> <a class="header-anchor" href="#rentals" aria-label="Permalink to “rentals”">​</a></h3><p>Stores all rental listings posted by landlords.</p><h3 id="booking-requests" tabindex="-1"><code>booking_requests</code> <a class="header-anchor" href="#booking-requests" aria-label="Permalink to “booking_requests”">​</a></h3><p>Stores all booking requests sent by tenants.</p><h3 id="rental-favorites" tabindex="-1"><code>rental_favorites</code> <a class="header-anchor" href="#rental-favorites" aria-label="Permalink to “rental_favorites”">​</a></h3><p>Stores tenant favorite rentals.</p><h3 id="phone-verification-challenges" tabindex="-1"><code>phone_verification_challenges</code> <a class="header-anchor" href="#phone-verification-challenges" aria-label="Permalink to “phone_verification_challenges”">​</a></h3><p>Stores OTP verification records.</p><h3 id="rental-private-details" tabindex="-1"><code>rental_private_details</code> <a class="header-anchor" href="#rental-private-details" aria-label="Permalink to “rental_private_details”">​</a></h3><p>Stores private landlord-only details like exact Google Maps pin.</p><h2 id="_11-table-relationships" tabindex="-1">11. Table Relationships <a class="header-anchor" href="#_11-table-relationships" aria-label="Permalink to “11. Table Relationships”">​</a></h2><p>This is a simple relation explanation.</p><ul><li>One user can have one profile.</li><li>One landlord can post many rentals.</li><li>One rental can receive many booking requests.</li><li>One tenant can send many requests, but only one active request per rental.</li><li>One tenant can save many favorite rentals.</li><li>One rental can have one private details row.</li></ul><p>You can describe it as:</p><ul><li><code>profiles</code> is connected to user identity</li><li><code>rentals</code> is connected to landlords</li><li><code>booking_requests</code> connects tenant and landlord around one rental</li></ul><h2 id="_12-dbms-concepts-used-in-this-project" tabindex="-1">12. DBMS Concepts Used In This Project <a class="header-anchor" href="#_12-dbms-concepts-used-in-this-project" aria-label="Permalink to “12. DBMS Concepts Used In This Project”">​</a></h2><p>This is one of the most important viva sections.</p><h3 id="_1-table-design" tabindex="-1">1. Table Design <a class="header-anchor" href="#_1-table-design" aria-label="Permalink to “1. Table Design”">​</a></h3><p>The system is divided into multiple related tables instead of putting everything in one table.</p><p>Why it is good:</p><ul><li>data is organized</li><li>repeated data is reduced</li><li>maintenance is easier</li></ul><h3 id="_2-primary-key" tabindex="-1">2. Primary Key <a class="header-anchor" href="#_2-primary-key" aria-label="Permalink to “2. Primary Key”">​</a></h3><p>Each main table has a primary key.</p><p>Examples:</p><ul><li><code>profiles.id</code></li><li><code>rentals.rental_id</code></li><li><code>booking_requests.booking_request_id</code></li></ul><p>Why it matters:</p><ul><li>every row can be identified uniquely</li></ul><h3 id="_3-foreign-key" tabindex="-1">3. Foreign Key <a class="header-anchor" href="#_3-foreign-key" aria-label="Permalink to “3. Foreign Key”">​</a></h3><p>Tables are connected using foreign keys.</p><p>Examples:</p><ul><li>rental belongs to a landlord</li><li>booking request belongs to rental, tenant, and landlord</li><li>favorites connect user and rental</li></ul><p>Why it matters:</p><ul><li>relationships stay valid</li><li>orphan records are reduced</li></ul><h3 id="_4-constraints" tabindex="-1">4. Constraints <a class="header-anchor" href="#_4-constraints" aria-label="Permalink to “4. Constraints”">​</a></h3><p>The system uses check constraints to stop invalid data.</p><p>Examples:</p><ul><li>rent must be greater than 0</li><li>room count must be greater than 0</li><li>tenant and landlord cannot be same user in one request</li><li>phone number must match Nepali format</li><li>shared fields must come in valid pairs</li></ul><p>Why it matters:</p><ul><li>invalid data is blocked by database itself</li></ul><h3 id="_5-enum-types" tabindex="-1">5. Enum Types <a class="header-anchor" href="#_5-enum-types" aria-label="Permalink to “5. Enum Types”">​</a></h3><p>The system uses enums for fixed values.</p><p>Examples:</p><ul><li>rental status</li><li>rental type</li><li>booking status</li><li>bathroom type</li></ul><p>Why it matters:</p><ul><li>values stay controlled</li><li>data becomes cleaner</li></ul><h3 id="_6-indexing" tabindex="-1">6. Indexing <a class="header-anchor" href="#_6-indexing" aria-label="Permalink to “6. Indexing”">​</a></h3><p>Indexes are used for faster search and filtering.</p><p>Examples:</p><ul><li>status index</li><li>user id index</li><li>created date index</li><li>booking request indexes</li></ul><p>Why it matters:</p><ul><li>faster query performance</li></ul><h3 id="_7-unique-index" tabindex="-1">7. Unique Index <a class="header-anchor" href="#_7-unique-index" aria-label="Permalink to “7. Unique Index”">​</a></h3><p>The project uses a partial unique index in booking requests.</p><p>Meaning:</p><ul><li>the same tenant cannot create more than one active request for the same rental</li></ul><p>This is a strong DBMS point.</p><h3 id="_8-trigger" tabindex="-1">8. Trigger <a class="header-anchor" href="#_8-trigger" aria-label="Permalink to “8. Trigger”">​</a></h3><p>The project uses triggers in multiple places.</p><p>Most important trigger:</p><ul><li>when landlord approves a request, rental becomes rented automatically and other pending requests are rejected automatically</li></ul><p>This is a strong example of database automation.</p><h3 id="_9-functions-in-pl-pgsql" tabindex="-1">9. Functions In PL/pgSQL <a class="header-anchor" href="#_9-functions-in-pl-pgsql" aria-label="Permalink to “9. Functions In PL/pgSQL”">​</a></h3><p>Database functions are used with triggers.</p><p>Why it matters:</p><ul><li>business logic is executed inside the database</li><li>system remains consistent even if frontend changes</li></ul><h3 id="_10-row-level-security" tabindex="-1">10. Row Level Security <a class="header-anchor" href="#_10-row-level-security" aria-label="Permalink to “10. Row Level Security”">​</a></h3><p>The project uses RLS in Supabase.</p><p>Simple meaning:</p><ul><li>each user can access only the data they are allowed to access</li></ul><p>Examples:</p><ul><li>tenants can only manage their own requests</li><li>landlords can only manage their own listings</li><li>private rental details are only available to owner</li></ul><h3 id="_11-realtime-database-features" tabindex="-1">11. Realtime Database Features <a class="header-anchor" href="#_11-realtime-database-features" aria-label="Permalink to “11. Realtime Database Features”">​</a></h3><p>Supabase Realtime is used for live update behavior.</p><p>Why it matters:</p><ul><li>when status changes, users see update quickly</li><li>better user experience</li></ul><h3 id="_12-migrations" tabindex="-1">12. Migrations <a class="header-anchor" href="#_12-migrations" aria-label="Permalink to “12. Migrations”">​</a></h3><p>Database changes are managed with migration files.</p><p>Why it matters:</p><ul><li>database design evolves in a controlled way</li><li>easy to track what changed and why</li></ul><h2 id="_13-triggers-used-in-this-project" tabindex="-1">13. Triggers Used In This Project <a class="header-anchor" href="#_13-triggers-used-in-this-project" aria-label="Permalink to “13. Triggers Used In This Project”">​</a></h2><h3 id="trigger-1-auto-create-profile-after-user-signup" tabindex="-1">Trigger 1: Auto Create Profile After User Signup <a class="header-anchor" href="#trigger-1-auto-create-profile-after-user-signup" aria-label="Permalink to “Trigger 1: Auto Create Profile After User Signup”">​</a></h3><p>When a new auth user is created, the system automatically creates a profile record.</p><p>Why useful:</p><ul><li>every logged in user gets a profile row automatically</li><li>no manual insert needed</li></ul><h3 id="trigger-2-auto-update-updated-at" tabindex="-1">Trigger 2: Auto Update <code>updated_at</code> <a class="header-anchor" href="#trigger-2-auto-update-updated-at" aria-label="Permalink to “Trigger 2: Auto Update updated_at”">​</a></h3><p>Several tables automatically refresh <code>updated_at</code> when row is modified.</p><p>Why useful:</p><ul><li>update history is maintained</li><li>no need to set time manually every time</li></ul><h3 id="trigger-3-booking-approval-trigger" tabindex="-1">Trigger 3: Booking Approval Trigger <a class="header-anchor" href="#trigger-3-booking-approval-trigger" aria-label="Permalink to “Trigger 3: Booking Approval Trigger”">​</a></h3><p>This is the best trigger in the whole project.</p><p>When one request is approved:</p><ul><li>rental status becomes <code>rented</code></li><li>other pending requests for that rental become <code>rejected</code></li></ul><p>Why useful:</p><ul><li>avoids manual work</li><li>prevents conflicting bookings</li><li>keeps system consistent</li></ul><h2 id="_14-why-trigger-was-important-in-this-project" tabindex="-1">14. Why Trigger Was Important In This Project <a class="header-anchor" href="#_14-why-trigger-was-important-in-this-project" aria-label="Permalink to “14. Why Trigger Was Important In This Project”">​</a></h2><p>Without trigger:</p><ul><li>frontend would need to update many tables manually</li><li>chance of mistakes would be higher</li><li>one request may get approved but rental might still remain available</li><li>other pending requests might not be rejected properly</li></ul><p>With trigger:</p><ul><li>one approval action automatically keeps whole system correct</li></ul><p>This is a very strong viva explanation.</p><h2 id="_15-security-concepts-used" tabindex="-1">15. Security Concepts Used <a class="header-anchor" href="#_15-security-concepts-used" aria-label="Permalink to “15. Security Concepts Used”">​</a></h2><h3 id="authentication-1" tabindex="-1">Authentication <a class="header-anchor" href="#authentication-1" aria-label="Permalink to “Authentication”">​</a></h3><p>Only logged in users can perform sensitive actions.</p><h3 id="authorization" tabindex="-1">Authorization <a class="header-anchor" href="#authorization" aria-label="Permalink to “Authorization”">​</a></h3><p>Role decides what a user can do.</p><ul><li>tenant cannot post listings</li><li>landlord cannot book own rental</li></ul><h3 id="rls" tabindex="-1">RLS <a class="header-anchor" href="#rls" aria-label="Permalink to “RLS”">​</a></h3><p>Even if someone tries to access database directly, policies restrict access.</p><h3 id="privacy-control" tabindex="-1">Privacy Control <a class="header-anchor" href="#privacy-control" aria-label="Permalink to “Privacy Control”">​</a></h3><p>Exact location and private contact sharing are controlled feature-by-feature.</p><h2 id="_16-how-realtime-is-used" tabindex="-1">16. How Realtime Is Used <a class="header-anchor" href="#_16-how-realtime-is-used" aria-label="Permalink to “16. How Realtime Is Used”">​</a></h2><p>Realtime is used so that when booking data changes, the latest state is reflected quickly in tenant and landlord views.</p><p>Examples:</p><ul><li>request status changes</li><li>approved request appears updated</li><li>shared location/contact appears without manual refresh in normal flow</li></ul><h2 id="_17-why-this-project-is-more-than-a-basic-crud-project" tabindex="-1">17. Why This Project Is More Than A Basic CRUD Project <a class="header-anchor" href="#_17-why-this-project-is-more-than-a-basic-crud-project" aria-label="Permalink to “17. Why This Project Is More Than A Basic CRUD Project”">​</a></h2><p>You can say:</p><p>“This project is not only add, edit, delete. It includes workflow management, privacy control, booking decision logic, trigger-based automation, role-based access, and realtime updates.”</p><p>That sentence is very good for viva.</p><h2 id="_18-non-technical-value-of-the-project" tabindex="-1">18. Non-Technical Value Of The Project <a class="header-anchor" href="#_18-non-technical-value-of-the-project" aria-label="Permalink to “18. Non-Technical Value Of The Project”">​</a></h2><p>This part is important because viva is not only about code.</p><h3 id="for-tenant" tabindex="-1">For Tenant <a class="header-anchor" href="#for-tenant" aria-label="Permalink to “For Tenant”">​</a></h3><ul><li>saves time finding room</li><li>request status is clear</li><li>only serious landlords share private details</li><li>easier communication</li></ul><h3 id="for-landlord" tabindex="-1">For Landlord <a class="header-anchor" href="#for-landlord" aria-label="Permalink to “For Landlord”">​</a></h3><ul><li>less confusion</li><li>organized incoming requests</li><li>can choose best tenant</li><li>no need to manage everything by phone only</li></ul><h3 id="for-both" tabindex="-1">For Both <a class="header-anchor" href="#for-both" aria-label="Permalink to “For Both”">​</a></h3><ul><li>more trust</li><li>more privacy</li><li>more transparency</li></ul><h2 id="_19-limitations-you-can-honestly-mention" tabindex="-1">19. Limitations You Can Honestly Mention <a class="header-anchor" href="#_19-limitations-you-can-honestly-mention" aria-label="Permalink to “19. Limitations You Can Honestly Mention”">​</a></h2><p>You can say the project is strong, but still has normal project limitations.</p><ul><li>no payment module</li><li>no admin panel</li><li>no advanced analytics dashboard</li><li>no chatbot or recommendation engine</li><li>image upload can still be improved more for full production hardening if needed</li></ul><p>Mentioning limitations makes your explanation mature and realistic.</p><h2 id="_20-future-improvements" tabindex="-1">20. Future Improvements <a class="header-anchor" href="#_20-future-improvements" aria-label="Permalink to “20. Future Improvements”">​</a></h2><p>Good future scope ideas:</p><ul><li>payment integration</li><li>admin verification panel</li><li>complaint and report system</li><li>landlord rating or tenant rating</li><li>chat system inside app</li><li>recommendation system based on area and budget</li><li>search by map radius</li></ul><h2 id="_21-short-system-flow-summary" tabindex="-1">21. Short System Flow Summary <a class="header-anchor" href="#_21-short-system-flow-summary" aria-label="Permalink to “21. Short System Flow Summary”">​</a></h2><h3 id="overall-flow" tabindex="-1">Overall Flow <a class="header-anchor" href="#overall-flow" aria-label="Permalink to “Overall Flow”">​</a></h3><ol><li>User logs in</li><li>Role is decided</li><li>Landlord posts rental</li><li>Tenant explores rental</li><li>Tenant sends booking request</li><li>Landlord reviews request</li><li>Landlord may share contact and later location</li><li>Landlord approves or rejects</li><li>On approval, rental becomes rented automatically</li><li>If tenant leaves later, landlord can make it available again</li></ol><h2 id="_22-simple-architecture-explanation" tabindex="-1">22. Simple Architecture Explanation <a class="header-anchor" href="#_22-simple-architecture-explanation" aria-label="Permalink to “22. Simple Architecture Explanation”">​</a></h2><p>Frontend:</p><ul><li>Next.js app</li></ul><p>Backend services:</p><ul><li>Supabase Auth</li><li>Supabase Postgres</li><li>Supabase Realtime</li><li>Supabase RLS</li></ul><p>Database side:</p><ul><li>tables</li><li>constraints</li><li>indexes</li><li>triggers</li><li>functions</li><li>policies</li></ul><h2 id="_23-best-viva-points-to-highlight" tabindex="-1">23. Best Viva Points To Highlight <a class="header-anchor" href="#_23-best-viva-points-to-highlight" aria-label="Permalink to “23. Best Viva Points To Highlight”">​</a></h2><p>If you get very little time, focus on these:</p><ol><li>The system supports two main roles: tenant and landlord.</li><li>It is not just a listing site, it manages complete booking request flow.</li><li>Trigger automatically marks rental as rented and rejects competing requests.</li><li>Partial unique index prevents duplicate active request from same tenant for same rental.</li><li>RLS protects private data and role-based access.</li><li>Contact number and exact map location are shared privately, not publicly.</li><li>Realtime is used so request updates are seen quickly.</li></ol><h2 id="_24-viva-questions-and-simple-answers" tabindex="-1">24. Viva Questions And Simple Answers <a class="header-anchor" href="#_24-viva-questions-and-simple-answers" aria-label="Permalink to “24. Viva Questions And Simple Answers”">​</a></h2><h3 id="q1-what-problem-does-your-project-solve" tabindex="-1">Q1. What problem does your project solve? <a class="header-anchor" href="#q1-what-problem-does-your-project-solve" aria-label="Permalink to “Q1. What problem does your project solve?”">​</a></h3><p>It solves the difficulty of finding rooms and managing rental requests in an organized, trackable, and privacy-aware way.</p><h3 id="q2-who-are-the-users-of-your-system" tabindex="-1">Q2. Who are the users of your system? <a class="header-anchor" href="#q2-who-are-the-users-of-your-system" aria-label="Permalink to “Q2. Who are the users of your system?”">​</a></h3><p>Mainly tenants and landlords. Guests can browse public listings.</p><h3 id="q3-why-did-you-use-database-triggers" tabindex="-1">Q3. Why did you use database triggers? <a class="header-anchor" href="#q3-why-did-you-use-database-triggers" aria-label="Permalink to “Q3. Why did you use database triggers?”">​</a></h3><p>To automate important business rules inside the database. For example, when a booking is approved, the rental becomes rented automatically and other pending requests are rejected.</p><h3 id="q4-why-did-you-use-rls" tabindex="-1">Q4. Why did you use RLS? <a class="header-anchor" href="#q4-why-did-you-use-rls" aria-label="Permalink to “Q4. Why did you use RLS?”">​</a></h3><p>To make sure each user only accesses data they are allowed to access.</p><h3 id="q5-what-is-the-most-important-dbms-concept-used" tabindex="-1">Q5. What is the most important DBMS concept used? <a class="header-anchor" href="#q5-what-is-the-most-important-dbms-concept-used" aria-label="Permalink to “Q5. What is the most important DBMS concept used?”">​</a></h3><p>Trigger, foreign key relationships, constraints, indexes, enum types, and row level security.</p><h3 id="q6-why-not-manage-everything-from-frontend-only" tabindex="-1">Q6. Why not manage everything from frontend only? <a class="header-anchor" href="#q6-why-not-manage-everything-from-frontend-only" aria-label="Permalink to “Q6. Why not manage everything from frontend only?”">​</a></h3><p>Because frontend-only logic is weaker and easier to break. Database rules make the system more consistent and secure.</p><h3 id="q7-how-do-you-stop-one-tenant-from-requesting-same-room-many-times" tabindex="-1">Q7. How do you stop one tenant from requesting same room many times? <a class="header-anchor" href="#q7-how-do-you-stop-one-tenant-from-requesting-same-room-many-times" aria-label="Permalink to “Q7. How do you stop one tenant from requesting same room many times?”">​</a></h3><p>By using business logic and a unique active-request index in the booking request table.</p><h3 id="q8-how-do-you-protect-landlord-privacy" tabindex="-1">Q8. How do you protect landlord privacy? <a class="header-anchor" href="#q8-how-do-you-protect-landlord-privacy" aria-label="Permalink to “Q8. How do you protect landlord privacy?”">​</a></h3><p>Exact location and private contact number are shared only with selected tenant requests, not with all users.</p><h3 id="q9-what-happens-when-one-tenant-is-approved" tabindex="-1">Q9. What happens when one tenant is approved? <a class="header-anchor" href="#q9-what-happens-when-one-tenant-is-approved" aria-label="Permalink to “Q9. What happens when one tenant is approved?”">​</a></h3><p>Rental status becomes rented automatically, other pending requests are rejected, and the selected tenant can continue communication.</p><h3 id="q10-is-this-project-only-crud" tabindex="-1">Q10. Is this project only CRUD? <a class="header-anchor" href="#q10-is-this-project-only-crud" aria-label="Permalink to “Q10. Is this project only CRUD?”">​</a></h3><p>No. It includes workflow logic, request approval system, trigger-based automation, RLS security, and realtime updates.</p><h2 id="_25-one-minute-viva-answer" tabindex="-1">25. One Minute Viva Answer <a class="header-anchor" href="#_25-one-minute-viva-answer" aria-label="Permalink to “25. One Minute Viva Answer”">​</a></h2><p>If teacher asks: “Explain your project.”</p><p>You can say:</p><p>“Our project is BasoBas, a rental accommodation management web application for tenants and landlords. Landlords can post room listings, manage them, and receive booking requests from multiple tenants. Tenants can browse rooms, save favorites, and send booking requests after phone verification. The landlord reviews requests, can share contact number and exact location privately, and then approve or reject the request. A major DBMS feature in our project is the use of triggers. When one request is approved, the database automatically marks the rental as rented and rejects all other pending requests for the same rental. We also used foreign keys, constraints, enum types, indexes, row level security, and Supabase Realtime. So the project is not only CRUD, but a complete workflow-based rental management system.”</p><h2 id="_26-three-minute-viva-answer" tabindex="-1">26. Three Minute Viva Answer <a class="header-anchor" href="#_26-three-minute-viva-answer" aria-label="Permalink to “26. Three Minute Viva Answer”">​</a></h2><p>If teacher asks for more detail, say:</p><p>“BasoBas is designed to solve a real rental problem. In normal room searching, landlords and tenants communicate in an unorganized way. Our system creates a proper process. First, users log in and choose role as tenant or landlord. Landlords can create rental listings with room details, facilities, rent, photos, and optional private Google Maps location. Tenants can browse available rooms and send a booking request. Multiple tenants can request one available rental, but the same tenant cannot create multiple active requests for the same room. The landlord sees all incoming requests in the dashboard, can review tenant details, call them, share contact number, and later share exact map location if comfortable. When the landlord approves one request, a database trigger automatically changes that rental status to rented and rejects all other pending requests. This is an important DBMS concept because it enforces business logic inside the database. We also used primary keys, foreign keys, check constraints, enum types, indexes, row level security, and realtime updates using Supabase. From a user point of view, the project improves trust, privacy, and clarity in the room rental process.”</p><h2 id="_27-final-conclusion" tabindex="-1">27. Final Conclusion <a class="header-anchor" href="#_27-final-conclusion" aria-label="Permalink to “27. Final Conclusion”">​</a></h2><p>BasoBas is a practical DBMS project because it shows:</p><ul><li>real world problem solving</li><li>multiple user roles</li><li>structured relational database design</li><li>trigger-based automation</li><li>secure access control</li><li>private and public data separation</li><li>realtime workflow</li></ul><p>This makes it a strong project both technically and functionally.</p>',319)])])}const m=a(n,[["render",r]]);export{u as __pageData,m as default};
